            "result": {"metadata": receipt},
        }
        input_images = {channel.role: str(channel.path) for channel in capture.channels}
        analysis_wall = time.perf_counter() - started
        receipt_timings = receipt["timing_seconds"]
        phase_timings = {
            "base_parallel_wall": float(
