BUNDLE_PATH = REVIEW_ROOT / "cloud_response_bundle.json"

app = FastAPI(
    title="AISIA 单RGB十二项云端 Worker Pydantic 合同",
    version="1",
    description=(
        "本服务仅用于本地验收正式 Worker 六字段信封、中文字段说明与模拟OSS结果。"
